class.description:
Each entry is a [Dictionary] of property values. A tick with no state reads as the latest earlier state. A tick with no input reads as no input. The server writes state and the controlling peer writes input.
[codeblock]
# on the controlling client
var predicted := timeline.latest_state_at_or_before(ack + 1)
if diverged(predicted, authoritative):
    for entry in timeline.inputs_in_range(ack + 1, now):
        _network_tick(entry.input, delta, entry.tick, false)
timeline.trim_before(ack)
[/codeblock]
